/*
 * Startup self-tests for this board.
 *
 * Checks that the board came up as its own configuration promised belong here
 * rather than in an application: they need vendor headers, linker symbols and
 * register maps that no portable application can see. The application supplies
 * only the reporting callback, so this file is free to include anything the
 * board needs.
 *
 * Worthwhile checks, drawn from the two shipped targets:
 *
 *   - The C heap cannot grow into memory bsp_ram_region() hands the
 *     application. Both shipped targets carry a regression guard for exactly
 *     this, because getting it wrong corrupts thread stacks silently.
 *   - The clock the board programmed matches BSP_SYSTEM_CLOCK_HZ.
 *   - The timebase driving the kernel tick is actually advancing.
 *   - The interrupt controller routes the console IRQ where the driver expects.
 */

#include <stddef.h>

#include "bsp/selftest.h"
#include "board_config.h"

/* TODO: Include the vendor HAL, linker-symbol externs and register headers the
 * checks below need. */

/* Reporting state, kept on the caller's stack so bsp_self_test() holds no
 * mutable state of its own. */
typedef struct {
    bsp_selftest_report_fn report;
    void                  *context;
    unsigned               failures;
} selftest_state;

static void check(selftest_state *state, int passed, const char *message)
{
    if (passed == 0) {
        state->failures++;
    }
    state->report(passed, message, state->context);
}

unsigned bsp_self_test(bsp_selftest_report_fn report, void *context)
{
    selftest_state state;

    if (report == NULL) {
        return 1U;
    }

    state.report   = report;
    state.context  = context;
    state.failures = 0U;

    /* TODO: Replace this placeholder with the board's real checks. Report each
     * through check(), including any measured values in the message so a
     * failure is diagnosable from the console log alone. */
    check(&state, 1, "board self-tests not yet implemented for this target");

    return state.failures;
}
